#define PI 3.14159265358979

#define VW(a,b) u.x *= a;u.y =(u.y - bt.x)/(bt.y-bt.x) * b;float x=u.x, y=u.y;

#define minc(a,b) if(y < float(a)) c = float(b);// 小于着色

#define mincc(y,a,b) if(y < float(a)) c = float(b);// 小于着色

#define M(a) mat2(cos(a),-sin(a),sin(a),cos(a))


// 定义

float hi = .01,  ba = 1., hui = .63;






// 画直线

float dline(vec2 u , vec4 p)

{

        vec2 a = u - p.xy,  b= p.zw-p.xy;

        float h = clamp(dot(a,b)/dot(b,b),0.,1.);

        return length(a - b * h);

}


// 边框

void H1(inout float c, vec2 u ,vec2 bt)

{

        VW(12., 4.)

        minc(4 , hi)

        if(abs(y-4.)<=.05 && mod(x/12.*8.,2.)<1.5)c=ba;

        minc(2.1, ba) 

        minc(2 , hui)

        #define F(e,f) if(y<e +.22 && mod( x ,2.)<e && mod( x * 40. +.5, 2.)<e)c=f;

        F(1., ba)
        F(.8, hi)

        minc(.1,ba)

        minc(0, ba)

}



