// 中间隔离，篱笆

void H3(inout float c, vec2 u ,vec2 bt)

{

        float d,s;

        VW(70.*PI, 6.)

        minc(6, hi)

        s = abs(sin(x))*4.;

        d = y - s - 2.;

        if(abs(d)<.2)c = ba;

        s *= .7;

        d = y - s - 2.;

        if(d <0.)c=ba;

        if(d < -.3)c= hui;

        if(y < .3)c=ba;

        if(y < 0.)c=hi;
}





