void H5(inout float c, vec2 u ,vec2 bt)

{

        float d,i,j;

        VW(3.,   8.)



        for(j=8.;j>-1.;j--)

        for(i=0.;i<6.;i++)

        {

                d = length(u - vec2(i,j));

                mincc(d, .9, ba)

                mincc(d, .8, hi)

                mincc(d, .7, ba)

                mincc(d, .6, hi)

                mincc(d, .5, ba)

                mincc(d, .4, hui)

        }

}





