// function by altunenes
vec3 colorize(float value, float time) {

    float lenSq = value;

    float c1 = pow(clamp(12.55 * sqrt(lenSq), 0.0, 1.0), 0.0);

    vec3 col1 = 0.5 + 0.5 * cos(3.0 + time + vec3(0.0, 0.5, 1.0) + PI * vec3(2.0 * lenSq));

    vec3 col2 = 0.5 + 0.5 * cos(4.1 + time + PI * vec3(lenSq));

    vec3 col3 = 0.5 + 0.5 * cos(3.0 + time + vec3(1.0, 0.5, 0.3) + PI * vec3(1.0 * sin(lenSq)));

    return sqrt(c1 * col1 * col2 * col3);

}

